import { createServerClient } from "@supabase/ssr";
import { NextResponse, type NextRequest } from "next/server";

import { env } from "@/lib/env";

/**
 * Erneuert das Session-Cookie bei jedem Request und liefert den
 * angemeldeten Benutzer samt Rolle zurueck.
 *
 * Ohne diesen Refresh laeuft die Session im Server-Rendering ab und der
 * Benutzer gilt nach einem Reload als abgemeldet.
 */
export async function updateSession(request: NextRequest) {
  let response = NextResponse.next({ request });

  const supabase = createServerClient(
    env.NEXT_PUBLIC_SUPABASE_URL,
    env.NEXT_PUBLIC_SUPABASE_ANON_KEY,
    {
      cookies: {
        getAll() {
          return request.cookies.getAll();
        },
        setAll(cookiesToSet) {
          for (const { name, value } of cookiesToSet) {
            request.cookies.set(name, value);
          }

          response = NextResponse.next({ request });

          for (const { name, value, options } of cookiesToSet) {
            response.cookies.set(name, value, options);
          }
        },
      },
    },
  );

  try {
    // getUser() validiert das Token gegen Supabase — getSession() wuerde dem
    // Cookie-Inhalt vertrauen und ist fuer Zugriffsentscheidungen ungeeignet.
    const {
      data: { user },
    } = await supabase.auth.getUser();

    let role: string | null = null;

    if (user) {
      const { data } = await supabase
        .from("profiles")
        .select("role")
        .eq("id", user.id)
        .maybeSingle();

      role = (data?.role as string | undefined) ?? null;
    }

    return { response, user, role };
  } catch {
    // Supabase nicht erreichbar oder fehlkonfiguriert: die Seite bleibt
    // bedienbar, der Benutzer gilt als nicht angemeldet. Geschuetzte Routen
    // sperren dadurch, statt dass die gesamte Anwendung ausfaellt.
    return { response, user: null, role: null };
  }
}
